<script setup lang="ts">
import {t,locale} from '../i18n'

import { onMounted,ref } from 'vue'
import DeviceSettings from '../components/DeviceSettings.vue'
import { Heart,Download,Upload,Plus,Copy,Check,LockKeyhole,CalendarDays } from 'lucide-vue-next'
import { useAlbum } from '../store'
import { api,type User } from '../api'
const album=useAlbum(),confirmUnbind=ref(false),busy=ref(false),error=ref(''),notice=ref(''),invitation=ref(''),copied=ref(false),restoreInput=ref<HTMLInputElement>(),pendingBackup=ref<File|null>(null),startDate=ref(''),revision=ref(''),settings=ref<Record<string,unknown>>({}),limit=ref(250),joinInvite=ref(''),joinPassword=ref(''),pairPreview=ref<{source:{name:string;photos:number;memories:number;revision:number};target:{name:string;photos:number;memories:number;revision:number}}|null>(null)
async function load(){try{const [space,system]=await Promise.all([api<{data:Record<string,unknown>;revision:string}>('/features/space_settings'),api<{backup_max_mb:number}>('/system')]);settings.value=!Array.isArray(space.data)?space.data:{};startDate.value=String(settings.value.together_date||'');revision.value=space.revision;limit.value=system.backup_max_mb}catch(e){error.value=(e as Error).message}}
async function saveDate(){busy.value=true;try{const result=await api<{revision:string}>('/features/space_settings',{method:'PUT',body:JSON.stringify({data:{...settings.value,together_date:startDate.value},revision:revision.value})});revision.value=result.revision;settings.value={...settings.value,together_date:startDate.value};await album.refresh();notice.value=t('已记住我们故事的开始')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function invite(){busy.value=true;error.value='';try{invitation.value=(await api<{invite:string}>('/invite',{method:'POST'})).invite}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function copy(){try{await navigator.clipboard.writeText(invitation.value);copied.value=true;setTimeout(()=>copied.value=false,2000)}catch{notice.value=t('请手动选择并复制邀请码')}}
async function backup(){busy.value=true;error.value='';try{const response=await fetch('/api/backup');if(!response.ok){const body=await response.json();throw new Error(body.error||t('备份失败'))};const url=URL.createObjectURL(await response.blob());const link=document.createElement('a');link.href=url;link.download=`footprint-${new Date().toISOString().slice(0,10)}.zip`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notice.value=t('已下载包含回忆、多图顺序和共同清单的备份')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
function choose(event:Event){pendingBackup.value=(event.target as HTMLInputElement).files?.[0]||null;(event.target as HTMLInputElement).value=''}
async function restore(){if(!pendingBackup.value)return;busy.value=true;error.value='';try{const form=new FormData();form.append('backup',pendingBackup.value);const result=await api<{added:number;skipped:number}>('/backup/restore',{method:'POST',body:form});pendingBackup.value=null;await album.refresh();await load();notice.value=t('导入完成：新增 {0} 张照片，跳过 {1} 张重复照片',[result.added,result.skipped])}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function unbind(){busy.value=true;error.value='';try{album.user=await api<User>('/auth/unbind',{method:'POST',body:'{}'});await album.refresh();confirmUnbind.value=false;await load();notice.value=t('已回到独立空间，你的照片仍然保留')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function previewPair(){busy.value=true;error.value='';pairPreview.value=null;try{pairPreview.value=await api('/auth/pair/preview',{method:'POST',body:JSON.stringify({invite:joinInvite.value.trim()})})}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function joinPair(){if(!pairPreview.value)return;busy.value=true;error.value='';try{album.user=await api<User>('/auth/pair',{method:'POST',body:JSON.stringify({invite:joinInvite.value.trim(),password:joinPassword.value,source_revision:pairPreview.value.source.revision,target_revision:pairPreview.value.target.revision})});await album.refresh();pairPreview.value=null;joinInvite.value='';joinPassword.value='';invitation.value='';await load();notice.value=t('你们已在同一个空间，双方回忆和清单已保留')}catch(e){error.value=(e as Error).message;pairPreview.value=null;joinPassword.value=''}finally{busy.value=false}}

onMounted(load)
</script>
<template><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="notice" class="settings-success" role="status"><Check :size="15"/>{{notice}}</p><div class="settings-grid"><section class="settings-card glass"><span class="stat-icon rose"><Heart :size="23"/></span><span class="eyebrow">BETTER TOGETHER</span><h2>{{t('相册里的我们')}}</h2><p class="muted">{{t('同一个空间，两个人共同收藏。')}}</p><div v-for="member in album.members" :key="member.id" class="member-row"><span class="avatar">{{member.name.slice(0,1)}}</span><strong>{{member.name}}</strong><span class="member-label">{{member.id===album.user?.id?t('你'):t('另一半')}}</span></div><template v-if="album.members.length<2"><p class="small muted invite-hint">{{t('邀请码 24 小时有效，仅可使用一次。新账号可在登录页选择“接受邀请”；已注册账号可在自己的“双人空间”粘贴邀请码。')}}</p><button class="primary" :disabled="busy" @click="invite"><Plus :size="16"/>{{invitation?t('重新生成邀请'):t('邀请另一半')}}</button><div v-if="invitation" class="invite-box"><input :value="invitation" readonly :aria-label="t('伴侣邀请码')"><button class="icon" :aria-label="t('复制邀请码')" @click="copy"><Check v-if="copied" :size="17"/><Copy v-else :size="17"/></button></div><div class="existing-pair"><h3>{{t('已有账号？加入 TA 的空间')}}</h3><p class="small muted">{{t('双方需先处于独立空间。输入 TA 发来的邀请码，预览后再决定配对。')}}</p><form class="pair-preview-form" @submit.prevent="previewPair"><label>{{t('TA 的邀请码')}}<input v-model="joinInvite" required minlength="64" maxlength="64" autocomplete="off" :disabled="busy" @input="pairPreview=null" :placeholder="t('粘贴完整邀请码')"></label><button class="secondary" :disabled="busy">{{t('预览配对')}}</button></form><div v-if="pairPreview" class="pair-confirm"><h3>{{t('与 {0} 一起收藏', [pairPreview.target.name])}}</h3><p>{{t('{0}：{1} 段回忆、{2} 张照片', [pairPreview.source.name,pairPreview.source.memories,pairPreview.source.photos])}}<br>{{t('{0}：{1} 段回忆、{2} 张照片', [pairPreview.target.name,pairPreview.target.memories,pairPreview.target.photos])}}</p><p class="small muted">{{t('确认后，你的全部回忆和照片将迁入 TA 的空间，双方均可查看和编辑。清单合并保留，恋爱起始日等同名设置沿用 TA 空间；内容相同的清单项去重，内容不同的保留两份。之后解除配对仍按照片所属账号拆分。')}}</p><form class="pair-confirm-form" @submit.prevent="joinPair"><label>{{t('确认你的账号密码')}}<input v-model="joinPassword" type="password" autocomplete="current-password" required maxlength="72"></label><button class="primary" :disabled="busy">{{busy?t('正在配对…'):t('确认配对并合并回忆')}}</button><button type="button" class="text-button" :disabled="busy" @click="pairPreview=null;joinPassword=''">{{t('取消')}}</button></form></div></div></template><div v-else class="together"><Heart :size="16"/>{{t('两个人，都在这里了。')}}</div><form @submit.prevent="saveDate"><label><CalendarDays :size="15"/>{{t('我们故事开始的日期')}}<input v-model="startDate" type="date"></label><button class="secondary" :disabled="busy">{{t('保存恋爱起始日')}}</button></form><div v-if="album.members.length>1" class="unbind-section"><button v-if="!confirmUnbind" class="text-button danger" @click="confirmUnbind=true">{{t('解除当前配对')}}</button><template v-else><p class="small muted">{{t('解除后，照片按当前所属账号分别保留，多图回忆按各自照片拆分；共同清单会各保留一份。双方将无法继续查看对方照片。此操作不会删除原图。')}}</p><button class="secondary danger" :disabled="busy" @click="unbind">{{t('确认解除配对')}}</button><button class="text-button" :disabled="busy" @click="confirmUnbind=false">{{t('取消')}}</button></template></div><div class="settings-note"><LockKeyhole :size="13"/>{{t('相册和原图，仅对这个空间内的两人开放')}}</div></section><section class="settings-card glass"><span class="stat-icon teal"><Download :size="23"/></span><span class="eyebrow">KEEP OUR MEMORIES SAFE</span><h2>{{t('回忆，多一份安心')}}</h2><p class="muted">{{t('备份包含原图、回忆分组、封面、照片顺序、备注和共同清单。')}}</p><button class="primary" :disabled="busy" @click="backup"><Download :size="17"/>{{busy?t('处理中…'):t('下载完整内容备份')}}</button><hr><h3>{{t('恢复备份／迁移旧版')}}</h3><p class="small muted">{{t('支持新版 ZIP、第一阶段照片 ZIP，以及原版后台导出的全量 ZIP。本次上限 {0}MB。追加导入、跳过重复记录，旧账号密码不会导入。旧备份必须包含本地图片，云端图片需先导出。', [limit])}}</p><input ref="restoreInput" type="file" accept=".zip,application/zip" hidden @change="choose"><button class="secondary" :disabled="busy" @click="restoreInput?.click()"><Upload :size="16"/>{{t('选择备份文件')}}</button><div v-if="pendingBackup" class="restore-confirm"><p>{{t('将把「{0}」中的回忆和照片导入当前空间。', [pendingBackup.name])}}</p><button class="primary" :disabled="busy" @click="restore">{{t('确认导入')}}</button><button class="text-button" :disabled="busy" @click="pendingBackup=null">{{t('取消')}}</button></div><hr><h3>{{t('导出足迹数据')}}</h3><div class="export-links"><a v-for="format in ['json','csv','gpx','geojson']" :key="format" :href="`/api/export/${format}`" class="secondary">{{format.toUpperCase()}}</a></div><p class="small muted">{{t('数据文件不包含原图，完整照片请使用 ZIP 备份。')}}</p></section><DeviceSettings/></div></template>
